import React, { useState, useEffect } from 'react';
import './SideNav.css';

const SideNav = () => {
  const [activeSection, setActiveSection] = useState('');
  const [isScrolled, setIsScrolled] = useState(false);

  const navItems = [
    { id: 'about', label: 'Introduction' },
    { id: 'works', label: 'Work Experience' },
    { id: 'journal', label: 'Studies' },
    { id: 'contact', label: 'Technical skills' }
  ];

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 100);

      // Detect active section
      const sections = navItems.map(item => document.getElementById(item.id));
      const scrollPosition = window.scrollY + 200;

      sections.forEach((section, index) => {
        if (section) {
          const sectionTop = section.offsetTop;
          const sectionBottom = sectionTop + section.offsetHeight;

          if (scrollPosition >= sectionTop && scrollPosition < sectionBottom) {
            setActiveSection(navItems[index].id);
          }
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <nav className={`side-nav ${isScrolled ? 'scrolled' : ''}`}>
      <div className="side-nav-content">
        {navItems.map((item, index) => (
          <div key={item.id} className="nav-item-wrapper">
            <button
              className={`side-nav-item ${activeSection === item.id ? 'active' : ''}`}
              onClick={() => scrollToSection(item.id)}
            >
              <span className="nav-line"></span>
              <span className="nav-label">{item.label}</span>
            </button>
          </div>
        ))}
      </div>
    </nav>
  );
};

export default SideNav;
